ns.Data.Rotations = {
  retribution = "Keep a Blessing (Blessing of Kings, Blessing of Might before 20) and a Seal up. Judge Seal of the Crusader first on targets that live a while, then switch to Seal of Command (slow two-hander, low spell power) or Seal of Righteousness (fast weapon, high spell power). Judgement (off the GCD) and Holy Strike on cooldown; Hammer of Justice or Repentance before Judgement with Seal of Command for the bonus vs stunned/incapacitated targets (macro /cast Repentance + /cast Judgement keeps the incapacitate). Hammer of Wrath below 20% (from 44). Exorcism on Undead/Demons (also a 30 yd tag). Consecration only when mana allows (8 s, costs almost twice Judgement + Holy Strike). AoE: Consecration, Holy Wrath vs Undead/Demons from 50. With Unsealed Wrath: let 2-3 Seal of Command copies stack, swap to Seal of Righteousness for one swing, then swap back (Wowhead).",
  protection = "Righteous Fury and Retribution Aura before the pull (Devotion Aura if another Paladin runs Retribution Aura). Keep Seal of Fury up: its Judgement taunts (10 yd) and adds damage; Judgement on cooldown for threat and to grab loose mobs, Swift Judgement as a second taunt. Consecration as long as mana allows (main AoE threat). Holy Shield (if talented) before Holy Strike with Shieldsworn; Holy Strike on cooldown; Exorcism and Holy Wrath on Undead/Demons; Hammer of Wrath when tanking 0-1 targets. Swap to Seal of Righteousness only when no taunt is needed. Sync Judgement and Holy Strike so the 5-second rule restores mana.",
  holy = "Flash of Light is the efficient main heal; Holy Light for heavy damage (Infusion of Light crits cut its cast); Holy Shock as an instant emergency/moving heal; Light's Vigil (1.5 s cast, expensive) on an ally before group damage, then Holy Shock on that ally to heal their whole party. Seal of Light while healing, Seal of Righteousness for damage. Questing damage: Seal of Righteousness, Judgement, Holy Strike, Exorcism (Undead/Demons), Holy Shock, Consecration if mana allows.",
  mana = "Do not refresh the Seal until it is about to run out; skip Judgement/Holy Strike if the next swing kills; turn leftover mana into Holy Light instead of eating (Icy Veins Ret). 5-second rule: casting stops Spirit regen for 5 s, so sync Judgement and Holy Strike and stop casting near the end of a fight (Icy Veins Prot/Holy, Wowhead Prot). Consecration is the big mana sink. Blessing of Wisdom when mana is the limit (Wowhead). Sanctified Judgement and Shield Specialization return mana; Reverence lets 30% of regen continue while casting.",
  seals = "Seal of Command for slow two-handers or low spell power (about 7 procs per minute regardless of speed, 0.203 SP coefficient after the 0.7 weapon modifier); Seal of Righteousness for fast weapons or high spell power (0.12 SP per hit with a two-hander, 0.10 one-hander). Judge Seal of the Crusader first for its 40 s Holy-damage debuff. Tanks: Seal of Fury (Judgement taunts). Healers: Seal of Light. Judgement no longer consumes the Seal; seal twisting only via Unsealed Wrath (31-point Retribution talent).",
  pvp_retribution = "Unconfirmed (foreverbattlegrounds, secondary): Hammer of Justice (10 yd) -> Judgement with Seal of Command (doubled on stunned targets) -> Holy Strike; Repentance as a second window; finish with Hammer of Wrath at 30 yd (instant with Champion of the Light 5/5). With Unsealed Wrath swing Seal of Command, swap Seals just before the stun. Blessing of Freedom replaces your other Blessing on that target.",
  sources = { "https://www.icy-veins.com/wow-forever/retribution-paladin-leveling", "https://www.wowhead.com/forever/guide/classes/paladin/retribution/dps-leveling-tips", "https://www.icy-veins.com/wow-forever/protection-paladin-leveling", "https://www.wowhead.com/forever/guide/classes/paladin/protection/tank-leveling-tips", "https://www.icy-veins.com/wow-forever/holy-paladin-leveling", "https://www.wowhead.com/forever/guide/classes/paladin/holy/healer-leveling-tips", "https://www.icy-veins.com/wow-forever/retribution-paladin-melee-dps-pve-stat-priority", "https://foreverbattlegrounds.com/classes/paladin/retribution/" },
  source_url = "https://www.icy-veins.com/wow-forever/retribution-paladin-leveling",
  checked = "2026-11-10",
}
